verus! {

    /// Given a one‐dimensional array `arr`, produce a two‐dimensional
    /// array `result` with exactly one row, where that row is
    /// element‐wise equal to `arr` and in the same order.
    fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
        ensures
            // exactly one row
            result.len() == 1,
            // the row has the same length as the input
            result[0].len() == arr.len(),
            // and each element is preserved
            forall |i: usize| i < arr.len() ==>
                result[0][i] == arr[i],
    {
        // build up an empty 2d vector
        let mut result: Vec<Vec<f32>> = Vec::new();
        // clone the input row
        let row: Vec<f32> = arr.clone();
        // push it as the single row
        result.push(row);
        result
    }

} // end verus!

